#!/usr/bin/env python3
import sys, os, re, json, csv, io, sqlite3, gzip, bz2, lzma, subprocess, datetime, pathlib, shlex

# Help text exact
HELP_TEXT = """trdsql - Execute SQL queries on CSV, LTSV, JSON, YAML and TBLN.

Usage
\ttrdsql [OPTIONS] [SQL(SELECT...)]

Options:
  -A string           analyze the file but only suggest SQL.
  -a string           analyze the file and suggest SQL.
  -config string      configuration file location.
  -db string          specify db name of the setting.
  -dblist             display db information.
  -debug              debug print.
  -driver string      database driver.  [ mysql | postgres | sqlite3 | sqlite3_ext ]
  -dsn string         database driver specific data source name.
  -help               display usage information.
  -q string           read query from the specified file.
  -t string           read table name from the specified file.
  -version            display version information.

Input Formats:
  -icsv               CSV format for input.
  -ig                 guess format from extension. (default "true")
  -ijson              JSON format for input.
  -iltsv              LTSV format for input.
  -itbln              TBLN format for input.
  -itext              text format for input.
  -iwidth             width specification format for input.
  -iyaml              YAML format for input.

Input options:
  -id string          field delimiter for input. (default ",")
  -ih                 the first line is interpreted as column names(CSV only).
  -ijq string         jq expression string for input(JSON/JSONL only).
  -ilr int            limited number of rows to read. (default 0)
  -inull value        value(string) to convert to null on input.
  -inum               add row number column.
  -ir int             number of rows to preread. (default 1)
  -is int             skip header row. (default 0)

Output Formats:
  -oat                ASCII Table format for output.
  -ocsv               CSV format for output.
  -ojson              JSON format for output.
  -ojsonl             JSON lines format for output.
  -oltsv              LTSV format for output.
  -omd                Markdown format for output.
  -oraw               Raw format for output.
  -otbln              TBLN format for output.
  -ovf                Vertical format for output.
  -oyaml              YAML format for output.

Output options:
  -oaq                enclose all fields in quotes for output.
  -ocrlf              use CRLF for output. End each output line with '\\r\\n' instead of '\\n'.
  -od string          field delimiter for output. (default ",")
  -oh                 output column name as header.
  -onowrap            do not wrap long lines(at/md only).
  -onull value        value(string) to convert from null on output.
  -oq string          quote character for output. (default "\\"")
  -out string         output file name.
  -out-without-guess  output without guessing (when using -out).
  -oz string          output compression format. [ gz | bz2 | zstd | lz4 | xz ]

Examples:
  $ trdsql "SELECT c1,c2 FROM test.csv"
  $ trdsql -oltsv "SELECT c1,c2 FROM test.json::.items"
  $ cat test.csv | trdsql -icsv -oltsv "SELECT c1,c2 FROM -"
"""

VERSION_TEXT = "trdsql version devel\n"

def timestamp():
    return datetime.datetime.now().strftime("%Y/%m/%d %H:%M:%S")

def eprint(msg):
    sys.stderr.write(msg + "\n")

def debug_log(msg, flags):
    if flags.get("debug"):
        sys.stderr.write(f"{timestamp()} {msg}\n")

# flag definitions
FLAG_DEFS = {
    "A": {"type":"string","default":""},
    "a": {"type":"string","default":""},
    "config": {"type":"string","default":""},
    "db": {"type":"string","default":""},
    "dblist": {"type":"bool","default":False},
    "debug": {"type":"bool","default":False},
    "driver": {"type":"string","default":""},
    "dsn": {"type":"string","default":""},
    "help": {"type":"bool","default":False},
    "h": {"type":"bool","default":False},
    "q": {"type":"string","default":""},
    "t": {"type":"string","default":""},
    "version": {"type":"bool","default":False},
    "icsv": {"type":"bool","default":False},
    "ig": {"type":"bool","default":True},
    "ijson": {"type":"bool","default":False},
    "iltsv": {"type":"bool","default":False},
    "itbln": {"type":"bool","default":False},
    "itext": {"type":"bool","default":False},
    "iwidth": {"type":"bool","default":False},
    "iyaml": {"type":"bool","default":False},
    "id": {"type":"string","default":","},
    "ih": {"type":"bool","default":False},
    "ijq": {"type":"string","default":""},
    "ilr": {"type":"int","default":0},
    "inull": {"type":"string","default":""},
    "inum": {"type":"bool","default":False},
    "ir": {"type":"int","default":1},
    "is": {"type":"int","default":0},
    "oat": {"type":"bool","default":False},
    "ocsv": {"type":"bool","default":False},
    "ojson": {"type":"bool","default":False},
    "ojsonl": {"type":"bool","default":False},
    "oltsv": {"type":"bool","default":False},
    "omd": {"type":"bool","default":False},
    "oraw": {"type":"bool","default":False},
    "otbln": {"type":"bool","default":False},
    "ovf": {"type":"bool","default":False},
    "oyaml": {"type":"bool","default":False},
    "oaq": {"type":"bool","default":False},
    "ocrlf": {"type":"bool","default":False},
    "od": {"type":"string","default":","},
    "oh": {"type":"bool","default":False},
    "onowrap": {"type":"bool","default":False},
    "onull": {"type":"string","default":""},
    "oq": {"type":"string","default":'"'},
    "out": {"type":"string","default":""},
    "out-without-guess": {"type":"bool","default":False},
    "oz": {"type":"string","default":""},
}

def parse_bool(s):
    if s in ("1","t","T","true","True","TRUE"):
        return True
    if s in ("0","f","F","false","False","FALSE"):
        return False
    raise ValueError

def print_help():
    sys.stderr.write(HELP_TEXT)

def flag_error(msg, rc=2):
    sys.stderr.write(msg + "\n")
    print_help()
    sys.exit(rc)

def parse_flags(argv):
    flags = {k: v["default"] for k,v in FLAG_DEFS.items()}
    positional = []
    i=0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            positional.extend(argv[i+1:])
            break
        if arg.startswith("-") and len(arg)>1:
            # strip leading dashes
            stripped = arg.lstrip("-")
            # handle = case
            if "=" in stripped:
                name, val = stripped.split("=",1)
                if name not in FLAG_DEFS:
                    flag_error(f"flag provided but not defined: -{name}")
                fdef = FLAG_DEFS[name]
                if fdef["type"] == "bool":
                    if val == "":
                        # Go flag with empty value? treat as true? But for string empty, ok.
                        # For bool empty, maybe error? We'll treat as true
                        flags[name] = True
                    else:
                        try:
                            flags[name] = parse_bool(val)
                        except ValueError:
                            flag_error(f'invalid boolean value "{val}" for -{name}: parse error')
                elif fdef["type"] == "string":
                    flags[name] = val
                elif fdef["type"] == "int":
                    if val == "":
                        flag_error(f'invalid value "" for flag -{name}: parse error')
                    try:
                        flags[name] = int(val)
                    except:
                        flag_error(f'invalid value "{val}" for flag -{name}: parse error')
                i+=1
                continue
            else:
                name = stripped
                if name not in FLAG_DEFS:
                    flag_error(f"flag provided but not defined: -{name}")
                fdef = FLAG_DEFS[name]
                if fdef["type"] == "bool":
                    flags[name] = True
                    i+=1
                    continue
                else:
                    # need next arg
                    if i+1 >= len(argv):
                        flag_error(f"flag needs an argument: -{name}")
                    # special case: if next arg looks like flag and type is string, Go still consumes it as value.
                    # We do same: consume next arg regardless.
                    val = argv[i+1]
                    if fdef["type"] == "int":
                        try:
                            flags[name] = int(val)
                        except:
                            flag_error(f'invalid value "{val}" for flag -{name}: parse error')
                    else:
                        flags[name] = val
                    i+=2
                    continue
        else:
            positional.append(arg)
            i+=1
    return flags, positional

# helpers for file handling
def detect_compression_by_magic(data):
    if data.startswith(b'\x1f\x8b'):
        return "gz"
    if data.startswith(b'BZ'):
        return "bz2"
    if data.startswith(b'\xfd7zXZ\x00'):
        return "xz"
    if data.startswith(b'\x28\xb5\x2f\xfd'):
        return "zstd"
    if data.startswith(b'\x04\x22\x4d\x18'):
        return "lz4"
    return ""

def decompress_data(data, comp):
    if comp == "gz":
        try:
            return gzip.decompress(data)
        except:
            return data
    if comp == "bz2":
        try:
            return bz2.decompress(data)
        except:
            return data
    if comp == "xz":
        try:
            return lzma.decompress(data)
        except:
            return data
    if comp == "zstd":
        try:
            import zstandard
            d = zstandard.ZstdDecompressor()
            return d.decompress(data)
        except:
            # try via external zstd if available? fallback
            return data
    if comp == "lz4":
        try:
            import lz4.frame
            return lz4.frame.decompress(data)
        except:
            return data
    return data

def read_raw_bytes(path):
    if path == "-":
        data = sys.stdin.buffer.read()
        # detect magic
        comp = detect_compression_by_magic(data)
        if comp:
            data = decompress_data(data, comp)
        return data
    else:
        # check extension for compression
        lower = path.lower()
        comp = ""
        if lower.endswith(".gz"):
            comp = "gz"
        elif lower.endswith(".bz2"):
            comp = "bz2"
        elif lower.endswith(".xz"):
            comp = "xz"
        elif lower.endswith(".zst") or lower.endswith(".zstd"):
            comp = "zstd"
        elif lower.endswith(".lz4"):
            comp = "lz4"
        else:
            # also check magic fallback
            try:
                with open(path, 'rb') as f:
                    head = f.read(6)
                    comp2 = detect_compression_by_magic(head)
                    if comp2:
                        comp = comp2
            except:
                pass
        if comp:
            # open with decompressor
            try:
                if comp == "gz":
                    with gzip.open(path, 'rb') as f:
                        return f.read()
                elif comp == "bz2":
                    with bz2.open(path, 'rb') as f:
                        return f.read()
                elif comp == "xz":
                    with lzma.open(path, 'rb') as f:
                        return f.read()
                elif comp == "zstd":
                    try:
                        import zstandard
                        with open(path, 'rb') as f:
                            d = zstandard.ZstdDecompressor()
                            return d.stream_reader(f).read()
                    except:
                        with open(path, 'rb') as f:
                            return f.read()
                elif comp == "lz4":
                    try:
                        import lz4.frame
                        with lz4.frame.open(path, 'rb') as f:
                            return f.read()
                    except:
                        with open(path, 'rb') as f:
                            return f.read()
            except FileNotFoundError:
                raise
            except Exception as e:
                # fallback to raw
                with open(path, 'rb') as f:
                    return f.read()
        else:
            with open(path, 'rb') as f:
                return f.read()

def read_text_file(path):
    data = read_raw_bytes(path)
    # decode as utf-8, replace errors?
    try:
        return data.decode('utf-8')
    except:
        return data.decode('utf-8', errors='replace')

def guess_input_format(path, flags):
    # priority: explicit flags
    # Order we determined: icsv > iltsv > ijson > itbln > iyaml > iwidth > itext
    # Actually check: if any explicit true, pick highest
    order = ["icsv","iltsv","ijson","itbln","iyaml","iwidth","itext"]
    for name in order:
        if flags.get(name):
            mapping = {
                "icsv":"csv",
                "iltsv":"ltsv",
                "ijson":"json",
                "itbln":"tbln",
                "iyaml":"yaml",
                "iwidth":"width",
                "itext":"text",
            }
            return mapping[name]
    # else guess from extension
    # strip compression suffix
    p = path
    lower = p.lower()
    for suf in [".gz",".bz2",".xz",".zst",".zstd",".lz4"]:
        if lower.endswith(suf):
            p = p[: -len(suf)]
            lower = p.lower()
            break
    ext = os.path.splitext(lower)[1]
    if ext == ".csv" or ext == ".tsv":
        return "csv"
    if ext == ".ltsv":
        return "ltsv"
    if ext == ".json" or ext == ".jsonl":
        return "json"
    if ext == ".tbln":
        return "tbln"
    if ext == ".yaml" or ext == ".yml":
        return "yaml"
    if ext == ".txt" and p.lower().endswith(".txt"):
        # For width, no extension guess, but for txt, default csv? Check earlier: w.txt with -iwidth vs default csv.
        # For txt, if no explicit, guess csv
        return "csv"
    # For "-" or unknown
    if p == "-":
        return "csv"
    # unknown extension -> csv
    # but also need to handle case where extension unknown, original logs "Set in CSV because the extension is unknown"
    return "csv"

