        elif isinstance(data, dict):
            # Could be single object, treat as one row? But original for file containing {"a": {"b":1}, "c":2} gave columns? Let's see: file containing '{"a": {"b":1}, "c":2}' with SELECT * gave '"{""b"":1}",2' -> That's weird. That file content is single JSON object not array, but they treated as one row with columns a,b? Actually they had file with '{"a": {"b":1}, "c":2}' and SELECT * gave one row with values "{""b"":1}",2. So they treat nested object as stringified? So we need to handle dict as single row with keys a,c.
            return [data]
        else:
