            # parse list
            rows = []
            current = {}
            for line in lines:
                stripped = line.strip()
                if not stripped:
                    continue
                if stripped.startswith("- "):
                    if current:
                        rows.append(current)
                        current = {}
                    # parse after "- "
                    rest = stripped[2:].strip()
                    if ":" in rest:
