def parse_tbln(text, flags):
    lines = text.splitlines()
    col_names = []
    data_rows = []
    found_name = False
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if stripped.startswith(";"):
            # metadata
            if stripped.startswith("; name:"):
                # parse column names: after "|"
                # e.g., "; name: | c1 | c2 |"
                parts = stripped.split("|")
                # parts[0] is "; name: ", parts[1:-1] are names, last is ""
                names = [p.strip() for p in parts[1:-1] if p.strip()!="" or True]
                # Filter empty? For "; name: | c1 | c2 |" -> parts = ['; name: ', ' c1 ', ' c2 ', '']
                # So names = ['c1','c2']
                col_names = [n.strip() for n in parts[1:] if n.strip()!=""]
                # Actually need to handle leading empty?
                # Remove empty strings
                col_names = [c for c in col_names if c]
                found_name = True
            elif stripped.startswith("; type:"):
                continue
            else:
                # comment? ignore
                continue
        elif stripped.startswith("|"):
            if not found_name:
                raise ValueError("unsupported line (c1 | c2)")
            # data row
            parts = stripped.split("|")
            # e.g., "| 1 | 2 |" -> ['', ' 1 ', ' 2 ', '']
            vals = [p.strip() for p in parts[1:-1]]
            data_rows.append(vals)
        else:
            # unsupported line
            raise ValueError(f"unsupported line ({stripped})")
    if not found_name:
        raise ValueError("unsupported line ...")
    # Convert to list of dicts?
    # For our import, we need column_names and rows as list of lists
    # Ensure each row has same length as col_names, pad if needed
    rows = []
    for vals in data_rows:
        # pad/truncate
        if len(vals) < len(col_names):
            vals += [""] * (len(col_names)-len(vals))
        elif len(vals) > len(col_names):
            vals = vals[:len(col_names)]
        rows.append(vals)
    return col_names, rows

